const request = require('request');

const options = {
  method: 'PUT',
  url: 'http://localhost:8080/rest/v2.1/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/viewer_documents/stamps/%7Bstamp_id%7D',
  headers: {'content-type': 'application/json'},
  body: {
    background_image: 'string',
    background_color: 'string',
    title: 'string',
    text: 'string',
    font_family: 'string',
    text_color: 'string',
    custom_properties: {user_name: true, company: true, date: true, time: true},
    font_style: {
      bold: true,
      italic: true,
      underline: true,
      strike_through: true,
      font_family: 'string',
      size: 1,
      text_color: 'string'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Put,
    RequestUri = new Uri("http://localhost:8080/rest/v2.1/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/viewer_documents/stamps/%7Bstamp_id%7D"),
    Content = new StringContent("{\"background_image\":\"string\",\"background_color\":\"string\",\"title\":\"string\",\"text\":\"string\",\"font_family\":\"string\",\"text_color\":\"string\",\"custom_properties\":{\"user_name\":true,\"company\":true,\"date\":true,\"time\":true},\"font_style\":{\"bold\":true,\"italic\":true,\"underline\":true,\"strike_through\":true,\"font_family\":\"string\",\"size\":1,\"text_color\":\"string\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

